-- ============================================================
-- SEED EXT 4: Módulo 18 — Nominalization (ex 144-215)
-- Novos tópicos: nominalização em resumos/abstracts TOEFL,
-- nominalização com -ment/-tion/-al/-ure/-ance/-ity avançado,
-- nominalização em passivas e structuras de ênfase
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'nominalization';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo nominalization não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 41: Nominalização com sufixos avançados
  (cid,41,144,'gap_fill','The _____ (discover) of the double helix structure by Watson and Crick represented a _____ (transform) moment in biological science.','discovery / transformative',NULL,'discover → discovery (-ery). transform → transformative (adj form as modifier).','medium'),
  (cid,41,145,'gap_fill','The _____ (intervene) of the central bank prevented a wider _____ (collapse) of the financial system.','intervention / collapse',NULL,'intervene → intervention (-tion). collapse → collapse (noun = same form).','medium'),
  (cid,41,146,'multiple_choice','Which nominalization pair is CORRECTLY formed?','govern → governance; fail → failure; attend → attendance; exclude → exclusion.','["govern → government; fail → failure; attend → attendance; exclude → exclusion","govern → governance; fail → failure; attend → attendance; exclude → exclusion.","govern → governance; fail → failing; attend → attendance; exclude → exclusion","govern → governance; fail → failure; attend → attendment; exclude → exclusion"]','All four are standard: governance, failure, attendance, exclusion.','medium'),
  (cid,41,147,'gap_fill','The _____ (comply) of member states with international _____ (commit) remains uneven and difficult to _____ (enforce).','compliance / commitments / enforce',NULL,'comply → compliance. commit → commitments. enforce = base form after "to" (infinitive).','hard'),
  (cid,41,148,'gap_fill','_____ (assess) of _____ (perform) should focus on _____ (achieve) and _____ (develop) rather than mere _____ (comply).','Assessment / performance / achievement / development / compliance',NULL,'Five nominalizations: assess→assessment, perform→performance, achieve→achievement, develop→development, comply→compliance.','hard'),
  (cid,41,149,'multiple_choice','Which sentence uses the MOST nominalizations while remaining grammatically correct?','The proliferation of non-state actors and the fragmentation of authority have increased the complexity of international security governance.','["Many non-state actors are proliferating and authority is fragmenting, which makes international security governance more complex.","The proliferation of non-state actors and the fragmentation of authority have increased the complexity of international security governance.","Non-state actors proliferate and authority fragments, increasing the complexity of international security governance.","Many non-state actors who proliferate and the fragmentation of authority have increased the complexity."]','Nominalizations: proliferation, fragmentation, complexity, governance (abstract nouns for nominalized style).','hard'),

  -- BLOCK 42: Nominalização em passivas e ênfase
  (cid,42,150,'gap_fill','The _____ (extend) of the project deadline _____ (grant/passive) following a formal _____ (request/passive) by the principal investigator.','extension / was granted / request',NULL,'Nominalizations: extension, (request kept as noun after "request").','medium'),
  (cid,42,151,'gap_fill','The _____ (grow) of urban populations has placed increasing _____ (press) on _____ (provide) of affordable housing.','growth / pressure / provision',NULL,'Nominalization chain: growth, pressure, provision.','medium'),
  (cid,42,152,'multiple_choice','Which rewording uses nominalization to create a MORE FORMAL academic style?','The government''s announcement of the new policy met with significant resistance from opposition groups.','["The government announced the new policy and opposition groups significantly resisted it.","The government''s announcement of the new policy met with significant resistance from opposition groups.","The government''s announcing of the new policy met with significant resistance from opposition groups.","The government announced new policy and got significant resistance."]','Nominalizations: announcement (announce→), resistance (resist→) = formal academic style.','medium'),
  (cid,42,153,'gap_fill','The rapid _____ (expand) of _____ (learn) platforms has created both _____ (opport) and _____ (challenge) for _____ (formal) education systems.','expansion / learning / opportunities / challenges / formal',NULL,'Nominal style: expansion, learning (gerund/noun), opportunities, challenges + adjective formal.','medium'),
  (cid,42,154,'gap_fill','The _____ (fail) of the _____ (negotiate) to produce an agreement led to the _____ (abandon) of the process.','failure / negotiations / abandonment',NULL,'Three nominalizations for a political setback narrative.','medium'),

  -- BLOCK 43: Nominalização em abstracts e introductions TOEFL
  (cid,43,155,'production','[Academic Writing task] Nominalize this sentence: "Researchers found that when students collaborated more, they performed better."','',NULL,'The research found that increased student collaboration was associated with improved academic performance. OR: Collaborative engagement among students was found to be positively associated with academic performance outcomes.','hard'),
  (cid,43,156,'production','[Academic Writing task] Nominalize: "When countries trade more freely, they develop economically."','',NULL,'Greater trade liberalization is associated with accelerated economic development. OR: Increased trade openness has been linked to stronger economic growth trajectories.','hard'),
  (cid,43,157,'gap_fill','This paper examines the _____ (relate) between _____ (access) to _____ (educate) and _____ (reduce) in _____ (poor).','relationship / access / education / reduction / poverty',NULL,'Five key nominalizations for an academic paper introduction.','medium'),
  (cid,43,158,'gap_fill','The _____ (contribute) of this study lies in its _____ (analyze) of the _____ (interact) between _____ (govern) quality and _____ (invest) in human capital.','contribution / analysis / interaction / governance / investment',NULL,'Five nominalizations for abstract/contribution section.','hard'),
  (cid,43,159,'multiple_choice','Which ABSTRACT sentence uses the most effective nominalization for academic writing?','The analysis of longitudinal data from 47 countries revealed significant variation in the relationship between institutional quality and economic performance.','["We analyzed longitudinal data from 47 countries and found that institutional quality and economic performance relate differently.","The analysis of longitudinal data from 47 countries revealed significant variation in the relationship between institutional quality and economic performance.","Analyzing longitudinal data from 47 countries showed us that institutional quality and economic performance relate differently in different cases.","We looked at data from 47 countries for a long time and found that institutions and economy work differently."]','Nominalizations: analysis, variation, relationship, institutional quality, economic performance = appropriate academic register.','medium'),

  -- BLOCK 44: Alternância verbo → nome com mudança de estrutura
  (cid,44,160,'multiple_choice','Which nominalization CORRECTLY restructures "Scientists discovered that temperatures increased rapidly"?','The discovery of rapid temperature increase has significant implications for climate modeling.','["The discovering of rapid temperature increasing has significant implications.","The discovery of rapid temperature increase has significant implications for climate modeling.","Scientists'' discovery of temperatures increasing rapidly has significant implications.","The discovered temperature increase has significant implications."]','discover → discovery + temperature increase (gerund phrase → noun phrase).','hard'),
  (cid,44,161,'gap_fill','Transform: "The government failed to respond adequately" → "The government''s _____ to respond _____ constituted a _____ of its duty."','failure / adequately / violation / neglect',NULL,'failure (failed→) + violation or neglect for constituted nominalizations.','hard'),
  (cid,44,162,'gap_fill','Transform: "They assumed that markets are efficient" → "The _____ of market _____ underpins classical economic _____ (theorize)."','assumption / efficiency / theory',NULL,'assume→assumption, efficient→efficiency, theorize→theory.','hard'),
  (cid,44,163,'gap_fill','The _____ (aware) of cognitive biases does not automatically lead to their _____ (eliminate) from _____ (decide) (make) processes.','awareness / elimination / decision-making',NULL,'aware→awareness, eliminate→elimination, decision-making = compound noun.','hard'),
  (cid,44,164,'gap_fill','The _____ (tend) to _____ (favor) short-term gains over long-term _____ (sustain) represents a significant _____ (constrain) on _____ (govern) quality.','tendency / favor / sustainability / constraint / governance',NULL,'Five academic nominalizations in a political economy statement.','hard'),

  -- BLOCK 45: TOEFL Reading
  (cid,45,165,'multiple_choice','[TOEFL Reading] "The implementation of trade liberalization policies accelerated economic integration." This nominalized sentence is preferable in academic writing because:','It allows "implementation" to function as the grammatical subject, compressing information densely.','["It uses more words","It is easier to read","It allows ''implementation'' to function as the grammatical subject, compressing information densely.","Verbs are not used in academic writing"]','Nominalization as subject = dense, formal, typical of academic writing.','medium'),
  (cid,45,166,'gap_fill','[TOEFL Reading] "The _____ (restrict) of academic freedom and the _____ (suppress) of independent _____ (research) are associated with lower _____ (innovate) and slower economic _____ (grow)." Best nominalizations?','restriction / suppression / research / innovation / growth',NULL,'Five nominalizations for academic freedom and innovation context.','medium'),
  (cid,45,167,'multiple_choice','[TOEFL Reading] "The organization''s commitment to transparency and accountability has strengthened public trust." Which pair of words are nominalizations?','Commitment and transparency and accountability (all three are nominalizations).','["Strengthened and public","Commitment and transparency and accountability (all three are nominalizations).","Organization and trust","Public and trust"]','commit→commitment, transparent→transparency, accountable→accountability = all nominalizations.','medium'),
  (cid,45,168,'gap_fill','[TOEFL Reading] "Economic _____ (grow) without social _____ (include) tends to produce political _____ (unstable), as _____ (marginal) populations seek _____ (represent) outside mainstream channels." Best nominalizations?','growth / inclusion / instability / marginalized / representation',NULL,'Growth, inclusion, instability, (marginalized as adj), representation.','hard'),

  -- BLOCK 46: TOEFL Speaking
  (cid,46,169,'production','[TOEFL Speaking — 45s] A reading discusses the benefits of urban green spaces. Summarize using at least 5 nominalizations.','',NULL,'The reading examines the multiple dimensions of benefit that urban green spaces provide to city residents. Research into the health implications of nature exposure has demonstrated a consistent association between access to parks and green infrastructure and reductions in stress, anxiety, and cardiovascular disease incidence. The environmental contribution of green spaces to urban resilience is also significant: vegetation reduces surface temperature, improves air quality through the absorption of particulate matter, and assists in stormwater management. The reading also highlights the social function of parks in facilitating informal interaction between residents across demographic boundaries — a function that has implications for the reduction of social isolation and the strengthening of community cohesion. Finally, the economic dimension of green space provision is addressed: research indicates that proximity to parks increases property values, representing a measurable financial return on public investment.','hard'),
  (cid,46,170,'production','[TOEFL Speaking — 45s] Discuss the importance of international cooperation on public health. Use nominalizations throughout.','',NULL,'The management of cross-border health threats requires levels of international cooperation and information-sharing that existing global health governance structures have often struggled to achieve. The COVID-19 pandemic exposed the inadequacy of international preparedness mechanisms and the insufficiency of coordination arrangements between the World Health Organization and national governments during the critical early period of outbreak detection and response. The absence of transparent and timely disclosure by affected countries during the initial stages of the pandemic significantly delayed the global response, with measurable consequences for subsequent mortality. The improvement of international health cooperation requires investment in surveillance infrastructure, the strengthening of reporting obligations, and the development of pre-negotiated agreements on vaccine and medical supply distribution during future health emergencies.','hard'),

  -- BLOCK 47: TOEFL Writing
  (cid,47,171,'production','[TOEFL Writing — 150 words] Write a paragraph on educational inequality using nominalizations throughout.','',NULL,'The persistence of educational inequality represents one of the most significant failures of social policy in contemporary societies. Disparities in educational attainment between children from high- and low-income families have proven remarkably resistant to policy intervention, despite substantial investment in programs targeting the early childhood development of disadvantaged populations. The explanation for this persistence lies partly in the cumulative nature of educational disadvantage: the accumulation of deficits in vocabulary acquisition, early literacy, and numerical reasoning that begins in infancy compounds over time, widening gaps that are already substantial by the point of school entry. Structural conditions — the concentration of poverty in specific geographic areas, variation in school quality across jurisdictions, and the absence of affordable childcare — reinforce and perpetuate these inequalities. Policy responses that address only educational inputs without confronting the socioeconomic conditions that shape educational readiness are unlikely to produce durable reductions in inequality.','hard'),
  (cid,47,172,'production','[TOEFL Writing — Error Correction] Transform these sentences to use nominalization: "Governments are increasingly ignoring environmental regulations. Scientists have discovered that climate is changing rapidly. When students engage more, they learn better. The failure of countries to cooperate led to many deaths."','',NULL,'Increasing governmental disregard for environmental regulations is a growing concern. The scientific discovery of rapid climate change has significant implications for policy. Greater student engagement is associated with improved learning outcomes. The failure of countries to cooperate [already nominalized] contributed to significantly higher mortality.','hard'),

  -- BLOCK 48: Consolidação final
  (cid,48,173,'production','[TOEFL Writing — 200 words] Write a paragraph on technological unemployment using heavy nominalization throughout.','',NULL,'The displacement of workers through technological automation — a process that economists have labeled technological unemployment — represents one of the defining structural challenges of contemporary economic governance. The acceleration of machine learning capabilities has expanded the range of occupational tasks susceptible to automation well beyond the routine physical and cognitive operations that earlier waves of technological change had displaced, extending now into domains previously thought to require specifically human judgment, creativity, and communication. The concentration of gains from this transformation among capital owners and highly skilled workers, combined with the compression of wages in middle-skill occupations facing the greatest competitive pressure from automation, has contributed to the widening of income inequality that research has consistently documented across most high-income economies since the early 1980s. Effective policy responses to technological unemployment require investment in educational retraining, reform of social insurance mechanisms to ensure adequate income support during occupational transitions, and serious consideration of the redistribution of productivity gains through tax policy and profit-sharing arrangements. The resolution of these challenges will depend not only on the quality of policy design but on the degree of political will to confront the distributional consequences of technological change rather than simply celebrating its aggregate efficiency gains.','hard'),
  (cid,48,174,'production','[TOEFL Speaking — 60s] Discuss what you believe are the most important skills for success in the 21st century. Use nominalization to express ideas in formal academic style.','',NULL,'The identification of competencies that will most reliably predict success in the twenty-first century is a question that employers, educators, and policymakers have approached from different directions and with somewhat different conclusions. There is, however, substantial convergence around several dimensions of capability. Adaptability — the capacity for rapid skill acquisition and the willingness to revise prior frameworks of understanding in response to new evidence — is widely regarded as foundational, given the acceleration of change in technological and economic environments. Critical reasoning, understood as the systematic evaluation of claims according to evidence rather than the acceptance of information from trusted authorities, is increasingly important in an informational environment characterized by the proliferation of misleading content. The cultivation of intercultural competence — the ability to communicate effectively and respectfully across cultural difference — has become essential in globally integrated professional environments. Finally, the development of what might be called collaborative intelligence — the ability not merely to work alongside others but to generate collective outcomes that exceed what individuals could achieve in isolation — is increasingly recognized as a distinguishing competency at the highest levels of organizational performance.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
